'use server'

import { updateTag } from 'next/cache'
import { insertPost } from '@/lib/posts'

export async function createPost(formData: FormData) {
  const title = String(formData.get('title') ?? '').trim()
  const content = String(formData.get('content') ?? '').trim()

  if (!title) {
    throw new Error('Title is required')
  }

  await insertPost({ title, content })

  // updateTag (not revalidateTag) expires the "posts" tag immediately, so the
  // next request blocks on fresh data instead of serving stale content
  // while revalidating in the background (read-your-own-writes).
  updateTag('posts')
}

